import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for StdDelegatingSerializer#isEmpty
 */
public class StdDelegatingSerializer_isEmpty_TriageGen0Test {

    private SerializerProvider prov;
    private JsonSerializer<?> delegateSerializer;
    private TestStdDelegatingSerializer serializer;

    /**
     * A subclass to allow testing of protected methods and access to the delegate
     */
    private static class TestStdDelegatingSerializer extends StdDelegatingSerializer {

        public TestStdDelegatingSerializer(JsonSerializer<?> delegate) {
            super(delegate);
        }

        @Override
        protected Object convertValue(Object value) {
            // For testing purposes, we can override this or rely on default
            // Default implementation usually returns value or uses a converter
            return super.convertValue(value);
        }
    }

    @Before
    public void setUp() {
        prov = mock(SerializerProvider.class);
        delegateSerializer = mock(JsonSerializer.class);
        serializer = new TestStdDelegatingSerializer(delegateSerializer);
    }

    @Test
    public void testIsEmpty_ReturnsTrueWhenDelegateReturnsTrue() {
        Object value = "testValue";
        when(delegateSerializer.isEmpty(eq(prov), eq(value))).thenReturn(true);

        boolean result = serializer.isEmpty(prov, value);

        assertTrue("Should return true when delegate returns true", result);
        verify(delegateSerializer).isEmpty(prov, value);
    }

    @Test
    public void testIsEmpty_ReturnsFalseWhenDelegateReturnsFalse() {
        Object value = "testValue";
        when(delegateSerializer.isEmpty(eq(prov), eq(value))).thenReturn(false);

        boolean result = serializer.isEmpty(prov, value);

        assertFalse("Should return false when delegate returns false", result);
        verify(delegateSerializer).isEmpty(prov, value);
    }

    @Test
    public void testIsEmpty_WithNullValue() {
        Object value = null;
        // In standard Jackson behavior, convertValue(null) is null
        when(delegateSerializer.isEmpty(eq(prov), eq(null))).thenReturn(true);

        boolean result = serializer.isEmpty(prov, value);

        assertTrue("Should handle null value correctly", result);
        verify(delegateSerializer).isEmpty(prov, null);
    }

    @Test
    public void testIsEmpty_WithConvertedValue() {
        // We need to ensure convertValue is triggered. 
        // Since we cannot easily mock the protected convertValue in the base class 
        // without overriding, we use a custom subclass to simulate a conversion.

        class ConvertingSerializer extends StdDelegatingSerializer {
            public ConvertingSerializer(JsonSerializer<?> delegate) {
                super(delegate);
            }
            @Override
            protected Object convertValue(Object value) {
                if ("convertMe".equals(value)) {
                    return "converted";
                }
                return value;
            }
        }

        ConvertingSerializer convertingSerializer = new ConvertingSerializer(delegateSerializer);
        Object input = "convertMe";
        Object expectedDelegateValue = "converted";

        when(delegateSerializer.isEmpty(prov, expectedDelegateValue)).thenReturn(true);

        boolean result = convertingSerializer.isEmpty(prov, input);

        assertTrue(result);
        verify(delegateSerializer).isEmpty(prov, expectedDelegateValue);
    }
}
